#!/usr/bin/env python3
"""Builds tools/menu-editor/menu-v2-data.js (from menu-v2.json) and tools/menu-editor/menu-editor-single.html
(index.html with menu-core.js, menu-v2-data.js and app.js inlined: one self-contained page for the published artifact)."""
import os, json
D = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'menu-editor')
data = json.load(open(os.path.join(D, 'menu-v2.json'), encoding='utf-8'))
open(os.path.join(D, 'menu-v2-data.js'), 'w', encoding='utf-8').write(
    '// generated by tools/build_menu_editor_single.py from menu-v2.json - do not edit\nwindow.MENU_V2 = ' + json.dumps(data, indent=1) + ';\n')
html = open(os.path.join(D, 'index.html'), encoding='utf-8').read()
for name in ['menu-core.js', 'menu-v2-data.js', 'app.js']:
    js = open(os.path.join(D, name), encoding='utf-8').read().replace('</script', '<\\/script')
    html = html.replace('<script src="%s"></script>' % name, '<script>\n' + js + '\n</script>')
assert 'src=' not in html
open(os.path.join(D, 'menu-editor-single.html'), 'w', encoding='utf-8').write(html)
print('Wrote menu-v2-data.js and menu-editor-single.html (%d bytes)' % len(html))
